import path from 'node:path';

function flatten(obj, prefix = '', out = new Set()) {
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? `${prefix}.${k}` : k;
    if (v && typeof v === 'object') flatten(v, key, out);
    else out.add(key);
  }
  return out;
}

// Load locale files by transpiling with esbuild-free approach: they are plain TS default exports.
async function loadLocale(file) {
  const src = fs.readFileSync(file, 'utf8').replace(/export default/, 'module.exports =');
  const tmp = `/tmp/loc-${path.basename(file, '.ts')}.cjs`;
  fs.writeFileSync(tmp, src);
  const mod = await import(`file://${tmp}?v=${Date.now()}`);
  return flatten(mod.default ?? mod);
}

const en = await loadLocale('client/locales/en-US.ts');
const zh = await loadLocale('client/locales/zh-CN.ts');

const dirs = ['client/pages/tickets', 'client/pages/service-desk', 'client/pages/home', 'client/routes.ts'];
const used = new Set();
for (const dir of dirs) {
  const files = fs.statSync(dir).isDirectory()
    ? fs.readdirSync(dir).filter((f) => f.endsWith('.tsx') || f.endsWith('.ts')).map((f) => path.join(dir, f))
    : [dir];
  for (const file of files) {
    const text = fs.readFileSync(file, 'utf8');
    for (const m of text.matchAll(/\bt\(\s*'([^']+)'/g)) used.add(m[1]);
    for (const m of text.matchAll(/(title|icon|breadcrumb)[^\n]*?'((?:tickets|home|inbox)\.[^']+)'/g)) used.add(m[2]);
    for (const m of text.matchAll(/^\s*(title|description|navigation):\s*'([^']+)'/gm)) used.add(m[2]);
  }
}
const ticketUsed = [...used].filter((k) => k.startsWith('tickets.') || k.startsWith('home') || k.startsWith('inbox'));
const missingEn = ticketUsed.filter((k) => !en.has(k));
const missingZh = ticketUsed.filter((k) => !zh.has(k));
console.log('used keys:', ticketUsed.length);
console.log('missing en:', missingEn);
console.log('missing zh:', missingZh);
const ticketEn = [...en].filter((k) => k.startsWith('tickets.'));
const ticketZh = [...zh].filter((k) => k.startsWith('tickets.'));
console.log('en ticket keys:', ticketEn.length, 'zh ticket keys:', ticketZh.length);
console.log('en-only:', ticketEn.filter((k) => !zh.has(k)));
console.log('zh-only:', ticketZh.filter((k) => !en.has(k)));
console.log('unused ticket keys:', ticketEn.filter((k) => !ticketUsed.includes(k)));
EOF
